 snapshots.push({lessonId:id,beforeFingerprint:before.contentFingerprint,currentFingerprint:fingerprint,location,sha256:sha(fs.readFileSync(location))});
 const event={id:`agent-source-scope-${id}-${date}-02-accepted`,lessonId:id,type:'source-scope',contentFingerprint:fingerprint,contentSnapshotLocation:location,reviewedSourceIds:l.sourceReferences.map(x=>x.sourceId),reviewedClaimIds:l.claimIds,completedOn:date,reviewer:actor,outcome:'accepted',sourceChecks:l.sourceReferences.map(s=>({sourceId:s.sourceId,url:s.url,checkedOn:date,access:'accessible',support:'supports-scoped-use',...sourceFindings[s.url]})),claimChecks:l.claimIds.map(claimId=>({claimId,outcome:'supported-with-qualifiers',notes:claimNotes[claimId]})),checks:{unitsAndDenominators:'pass',modelAssumptions:'pass',claimQualifiers:'pass',dependencyAndVisualScope:'pass'},notes:notes[id]+' Acceptance is limited to this content/source snapshot; it does not certify complete infrastructure coverage, current operation of every referenced project, rendered-browser behavior, human expertise or learning effectiveness.'};
